using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace FlowRunFinder
{
    [Export(typeof(IXrmToolBoxPlugin))]
    [ExportMetadata("Name", "Flow Run Finder")]
    [ExportMetadata("Description", "Filter cloud flow runs based on date/time and navigate directly to the flow run in your environment.")]
    [ExportMetadata("BackgroundColor", "#0078D4")]
    [ExportMetadata("PrimaryFontColor", "#FFFFFF")]
    [ExportMetadata("SecondaryFontColor", "#C7E0F4")]
    [ExportMetadata("BigImageBase64", "")]
    [ExportMetadata("SmallImageBase64", "")]
    public class FlowRunFinderPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
            => new FlowRunFinderControl();
    }
}
